def titlecase(text):
    """Upper-case the first letter of every word and lower-case the rest."""
    out = []
    prev_alpha = False
    for ch in text:
        out.append(ch.lower() if prev_alpha else ch.upper())
        prev_alpha = ch.isalpha()
    return "".join(out)

